// This file is generated by AI.

// 文件行徽标的两张索引表: 把逐行线性查找压成一次 Map 查表。
//
// 逐行读 store 做线性查找是 N × M, 文件多时进列表与滚动都会卡。性能对比只打印不断言:
// 数字随机器变化, 阈值断言在 CI 上必然不稳, 因此只核对新旧做法结果一致。

import { describe, expect, it } from 'vitest';

import type { GitStatus } from '../src/commands/git';
import { buildDiagnosticIndex } from '../src/diagnostics/model';
import { buildGitLetterIndex, normalizeRelPath } from '../src/git/util';

function gitStatusOf(count: number): GitStatus {
  const staged = Array.from({ length: count }, (_, i) => ({
    path: `game/scene/scene-${i}.txt`,
    status: 'M' as const,
  }));
  const unstaged = Array.from({ length: count }, (_, i) => ({
    path: `game/background/bg-${i}.png`,
    status: 'U' as const,
  }));
  return { initialized: true, branch: 'main', staged, unstaged } as unknown as GitStatus;
}

describe('buildGitLetterIndex', () => {
  it('索引已暂存与未暂存, 且已暂存优先', () => {
    const status = {
      initialized: true,
      staged: [{ path: 'a.txt', status: 'M' }],
      unstaged: [
        { path: 'a.txt', status: 'U' },
        { path: 'b.txt', status: 'U' },
      ],
    } as unknown as GitStatus;

    const index = buildGitLetterIndex(status);
    expect(index.get('a.txt')).toBe('M');
    expect(index.get('b.txt')).toBe('U');
    expect(index.size).toBe(2);
  });

  it('归一化: 反斜杠、前导斜杠与大小写差异都能命中同一个键', () => {
    const status = {
      initialized: true,
      staged: [{ path: 'Game\\Scene\\Start.TXT', status: 'A' }],
      unstaged: [],
    } as unknown as GitStatus;

    const index = buildGitLetterIndex(status);
    expect(index.get(normalizeRelPath('game/scene/start.txt'))).toBe('A');
    expect(index.get(normalizeRelPath('/Game/Scene/Start.txt'))).toBe('A');
  });

  it('没有仓库时是空表', () => {
    expect(buildGitLetterIndex(null).size).toBe(0);
    expect(buildGitLetterIndex({ initialized: false } as unknown as GitStatus).size).toBe(0);
  });

  it('同样条数下, 建表 + 查表比逐行线性查找快一个数量级', () => {
    const count = 2000;
    const status = gitStatusOf(count);
    const rels = Array.from({ length: count }, (_, i) => `game/scene/scene-${i}.txt`);

    // 旧做法: 每一行都在两份列表上线性 find, 每次比较都跑三遍字符串处理
    const legacyStart = performance.now();
    let legacyHit = 0;
    for (const rel of rels) {
      const normalized = rel.replace(/\\/g, '/').replace(/^\/+/, '').toLowerCase();
      const find = (files: { path: string; status: string }[] | undefined) =>
        files?.find((file) => file.path.replace(/\\/g, '/').replace(/^\/+/, '').toLowerCase() === normalized);
      const letter = find(status.staged)?.status ?? find(status.unstaged)?.status ?? null;
      if (letter) legacyHit += 1;
    }
    const legacyMs = performance.now() - legacyStart;

    // 新做法: 建表一次, 每行一次 Map 查表
    const indexStart = performance.now();
    const index = buildGitLetterIndex(status);
    let newHit = 0;
    for (const rel of rels) if (index.get(normalizeRelPath(rel))) newHit += 1;
    const indexMs = performance.now() - indexStart;

    console.log(
      `[徽标索引] N=${count} M=${count * 2}  旧做法 ${legacyMs.toFixed(1)}ms  →  新做法 ${indexMs.toFixed(1)}ms` +
        `  (${(legacyMs / Math.max(indexMs, 0.01)).toFixed(0)}× 加速)`
    );

    // 语义必须一致 (性能对比只有在结果相同时才有意义)
    expect(newHit).toBe(legacyHit);
    expect(newHit).toBe(count);
  });
});

describe('buildDiagnosticIndex', () => {
  it('只统计错误与警告, 跳过其它级别与空数组', () => {
    const index = buildDiagnosticIndex({
      '/p/game/scene/a.txt': [{ severity: 1 }, { severity: 2 }, { severity: 2 }, { severity: 3 }],
      '/p/game/scene/b.txt': [{ severity: 4 }],
      '/p/game/scene/c.txt': [],
    });
    expect(index.get('/p/game/scene/a.txt')).toEqual({ errors: 1, warnings: 2 });
    expect(index.has('/p/game/scene/b.txt')).toBe(false);
    expect(index.has('/p/game/scene/c.txt')).toBe(false);
  });

  it('没有诊断时是空表', () => {
    expect(buildDiagnosticIndex({}).size).toBe(0);
  });
});
